package com.bankpli.javabank.swift;import java.math.BigDecimal;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/swift")public class SwiftController{private final SwiftPaymentService payments;private final BicValidator bics;private final FxService fx;private final CurrencyFormatter formatter;public SwiftController(SwiftPaymentService p,BicValidator b,FxService f,CurrencyFormatter c){payments=p;bics=b;fx=f;formatter=c;}@GetMapping("/bic/{bic}")public Map<String,Boolean>bic(@PathVariable String bic){return Map.of("valid",bics.isValid(bic));}@PostMapping("/payments")public SwiftPaymentService.Result payment(@RequestBody SwiftPaymentService.Payment p){return payments.process(p);}@GetMapping("/fx")public Map<String,Object>fx(@RequestParam BigDecimal amount,@RequestParam String from,@RequestParam String to){return Map.of("rate",fx.rate(from,to),"converted",fx.convert(amount,from,to));}@GetMapping("/format")public Map<String,String>format(@RequestParam BigDecimal amount,@RequestParam String currency,@RequestParam(defaultValue="en-US")String locale){return Map.of("formatted",formatter.format(amount,currency,Locale.forLanguageTag(locale)),"picture",formatter.picture(amount));}}
